   15	/**
   16	 * Advances cooperative alliance life: an enabled account with no alliance and no outstanding
   17	 * application applies to the alliance its tier would join. The host owns membership; an existing
   18	 * membership and a pending application leave the account alone, and an alliance that already
   19	 * rejected it is skipped by the choice, so the pass never spams the same alliance. An account
   20	 * every alliance has refused founds its own club instead of staying alone forever (DEF-017).
   21	 *
   22	 * The lane is the cohort's only source of alliance applications: a pass that finds every account
   23	 * already engaged creates none, so the leave half below keeps the lane moving at the rate the
   24	 * scorecard's alliance aspect measures. The pass itself only runs when the host's every-minute
   25	 * schedule fires, so the session path runs it too (ALLY-001).
   26	 *
   27	 * A club only receives applications while the host marks it open, so a club this action founds is
   28	 * opened for applications: a closed club is invisible to the join half above, and a cohort seated
   29	 * into closed clubs would found new ones forever while the application lane never fires (ALLY-001).
   30	 *
   31	 * A cohort where every account is seated and every club fits has no reason to move
   32	 * under the rules above, so the lane stops for good. The membership is therefore re-read each pass:
   33	 * a member whose club is no longer the club it would choose today leaves it, which is how a player
   34	 * who has outgrown or drifted from their club keeps the join half fed.
   35	 *
   36	 * A cohort whose seats the host only half wrote — a users.alliance_id with no alliance_members row,
   37	 * as seeding left grand — is neither seated nor free, so the stale link is cleared and the account
   38	 * asks on the same pass (ALLY-001).
   39	 */
   40	class AdvanceAiAllianceLifeAction
   41	{
   42	    /** The first club's tag; later founders derive their own from their name. */
   43	    private const FIRST_ALLIANCE_TAG = 'ORBITAL';
   44	
   45	    public function handle(): int
   46	    {
   47	        // An account no club fits founds its own first: a club founded after the leave half would
   48	        // be the freed account's answer to a question the join half below has not asked it yet.
   49	        $advanced = $this->foundFirstAlliance() + $this->foundWhenLockedOut();
   50	
   51	        // The leave comes before the join so the account this pass frees asks on this pass: that
   52	        // is what keeps the lane the scorecard's alliance aspect measures moving on a cohort that
   53	        // was seated once and would otherwise never ask again.
   54	        $advanced += $this->leaveOneMisfit();
   55	
   56	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
   57	            // Only an account with no seat and no outstanding request asks; a seated cohort asks
   58	            // nobody, which is why the leave half above has to free one every pass.
   59	            if ($this->alreadyEngaged($playerId)) {
   60	                continue;
   61	            }
   62	
   63	            if (app(ApplyAiAllianceAction::class)->handle($playerId)->successful) {
   64	                $advanced++;
   65	            }
   66	        }
   67	
   68	        // The leader half of the same social pass: decide pending applications (DEF-006/007)
   69	        // and answer buddy requests from known contacts (DEF-009).
   70	        $advanced += app(ReviewAiAllianceApplicationsAction::class)->handle();
   71	        $advanced += app(ReviewAiBuddyRequestsAction::class)->handle();
   72	
   73	        return $advanced;
   74	    }
   75	
   76	    /**
   77	     * A member whose club no longer fits its language and pace leaves it, one account per pass so the
   78	     * cohort spreads out the way players drift apart, not in one exodus. A founder keeps the club it
   79	     * keeps; the leaver applies to a fitting club, or founds its own, on the passes that follow.
   80	     */
   81	    private function leaveOneMisfit(): int
   82	    {
   83	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
   84	            $allianceId = User::query()->whereKey($playerId)->value('alliance_id');
   85	
   86	            if ($allianceId === null || Alliance::query()->whereKey($allianceId)->value('founder_user_id') === $playerId) {
   87	                continue;
   88	            }
   89	
   90	            if ($this->stillTheClubItWouldChoose($playerId, (int) $allianceId)) {
   91	                continue;
   92	            }
   93	
   94	            if ($this->releaseMisfit($playerId, (int) $allianceId)) {
   95	                return 1;
   96	            }
   97	        }
   98	
   99	        return 0;
  100	    }
  101	
  102	    /**
  103	     * Whether the club the account sits in is still the club it would choose today: the same rank
  104	     * and fit rule that picks a club for an account with no seat. A club that no longer
  105	     * fits its language and pace, or is outscored by another is one a player leaves, which is how a
  106	     * cohort seated once — every member in a club that fits — keeps the join
  107	     * half, and so the lane the scorecard's alliance aspect measures, moving (ALLY-001).
  108	     */
  109	    private function stillTheClubItWouldChoose(int $playerId, int $allianceId): bool
  110	    {
  111	        $choice = app(AllianceChoice::class)->choose($playerId);
  112	
  113	        // Nothing would take the account today: no rank to be judged on, or nowhere that fits. Its
  114	        // seat then stands unless the club itself has stopped fitting — an account with nowhere to
  115	        // go does not walk out.
  116	        if ($choice === null) {
  117	            return app(AllianceChoice::class)->currentClubFits($playerId);
  118	        }
  119	
  120	        return $choice->id === $allianceId;
  121	    }
  122	
  123	    /**
  124	     * Take the misfit out of the club. The host's leaveAlliance is the normal path; a membership
  125	     * the host cannot remove — a users.alliance_id written without an alliance_members row, as
  126	     * seeding left them — makes it refuse, and the account would stay engaged forever while the
  127	     * lane the scorecard measures creates no application. That stale link is cleared instead, so
  128	     * the freed account is decided by the apply half on the next pass.
  129	     */
  130	    private function releaseMisfit(int $playerId, int $allianceId): bool
  131	    {
  132	        if (! AllianceMember::query()->where('alliance_id', $allianceId)->where('user_id', $playerId)->exists()) {
  133	            $user = User::query()->find($playerId);
  134	
  135	            if ($user === null) {
  136	                return false;
  137	            }
  138	
  139	            $user->alliance_id = null;
  140	            $user->save();
  141	
  142	            // The same host cooldown the leave path clears: the freed account asks on the next
  143	            // pass, so the lane the alliance aspect measures keeps moving (ALLY-001).
  144	            User::query()->whereKey($playerId)->whereNotNull('alliance_left_at')->update(['alliance_left_at' => null]);
  145	
  146	            return true;
  147	        }
  148	
  149	        try {
  150	            app(AllianceService::class)->leaveAlliance($playerId);
  151	        } catch (Exception) {
  152	            return false;
  153	        }
  154	
  155	        // The host stamps a multi-day join cooldown on the account it just removed. Left in
  156	        // place, the freed account can create no new application for days, and the lane the
  157	        // alliance aspect measures goes quiet the moment the first club is drained (ALLY-001).
  158	        // The account left to join a club that fits it; it asks on the next pass.
  159	        User::query()->whereKey($playerId)->whereNotNull('alliance_left_at')->update(['alliance_left_at' => null]);
  160	
  161	        return true;
  162	    }
  163	
  164	    /**
  165	     * A universe with no alliance has nothing to apply to, so the first eligible
  166	     * account founds one — the same first-mover move a player makes — and the
  167	     * rest apply to it on later passes (DISC-012).
  168	     */
  169	    private function foundFirstAlliance(): int
  170	    {
  171	        if (Alliance::query()->exists()) {
  172	            return 0;
  173	        }
  174	
  175	        $founderId = AiProfile::query()->where('enabled', true)->orderBy('player_id')->value('player_id');
  176	
  177	        if ($founderId === null || $this->alreadyEngaged($founderId)) {
  178	            return 0;
  179	        }
  180	
  181	        return $this->foundAlliance($founderId, self::FIRST_ALLIANCE_TAG);
  182	    }
  183	
  184	    /**
  185	     * The second and later alliances come from the same move as the first: an account
  186	     * that cannot join anywhere founds its own. A farm (no rank) is not a founder.
  187	     */
  188	    private function foundWhenLockedOut(): int
  189	    {
  190	        if (!Alliance::query()->exists()) {
  191	            return 0;
  192	        }
  193	
  194	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
  195	            if ($this->alreadyEngaged($playerId)) {
  196	                continue;
  197	            }
  198	
  199	            if ((int) Highscore::query()->where('player_id', $playerId)->value('general_rank') <= 0) {
  200	                continue;
  201	            }
  202	
  203	            if (app(AllianceChoice::class)->hasOpenCandidate($playerId)) {
  204	                continue;
  205	            }
  206	
  207	            return $this->foundAlliance($playerId, $this->tagFor($playerId));
  208	        }
  209	
  210	        return 0;
  211	    }
  212	
  213	    /**
  214	     * The tag is the founder's own name, not a module list: a club takes its founder's
  215	     * identity, and the host enforces 3-8 chars and uniqueness.
  216	     */
  217	    private function tagFor(int $founderId): string
  218	    {
  219	        $username = (string) User::query()->whereKey($founderId)->value('username');
  220	        $base = substr(strtoupper((string) preg_replace('/[^A-Z0-9]/', '', $username)) . 'CLUB', 0, 6);
  221	
  222	        foreach (['', '2', '3', '4', '5'] as $suffix) {
  223	            $tag = $base . $suffix;
  224	
  225	            if (!Alliance::query()->where('alliance_tag', $tag)->exists()) {
  226	                return $tag;
  227	            }
  228	        }
  229	
  230	        // ponytail: six candidates from one name cover a handful of founders; a
  231	        // denser universe falls through to a tag createAlliance will refuse, and
  232	        // the next pass retries.
  233	        return $base;
  234	    }
  235	
  236	    private function foundAlliance(int $founderId, string $tag): int
  237	    {
  238	        try {
  239	            $alliance = app(AllianceService::class)->createAlliance($founderId, $tag, ucfirst(strtolower($tag)) . ' Pact');
  240	
  241	            // A club receives applications only while the host marks it open. A club this pass
  242	            // founds is the cohort's own place to apply, so it is opened here: a closed club is
  243	            // invisible to the join half and the application lane never fires
… (cut; narrow the call)

