242	            // founds is the cohort's own place to apply, so it is opened here: a closed club is
243	            // invisible to the join half and the application lane never fires (ALLY-001).
244	            if (! $alliance->is_open) {
245	                $alliance->is_open = true;
246	                $alliance->save();
247	            }
