 16	/**
 17	 * Picks the alliance a human-like account would apply to, from host data alone.
 18	 *
 19	 * The join decision is "which club will actually take me, and can I keep up with it" (alliance
 20	 * FAQ). The account's rank against the population stays the first filter: a weak account looks
 21	 * for a mass/open club, a strong one for a high points-per-member core, a mid one balances the
 22	 * two (all in resources/behavior/alliance_fit.yaml). Among the clubs the rank admits, the fit rule
 23	 * decides: the applicant's language and activity band against the club's, both read from host
 24	 * state — the club's through its founder. A club no account of this language and pace fits is
 25	 * never asked, so the account stays free for the pass's founder half; the club that then appears
 26	 * carries that account's language and pace, so a cohort spreads over clubs instead of piling into
 27	 * one. An alliance that already rejected the account is never re-applied to.
 28	 */
 29	class AllianceChoice
 30	{
 31	    private const FIT_FILE = '/resources/behavior/alliance_fit.yaml';
 32	
 33	    /** @var array<string, mixed>|null */
 34	    private array|null $policy = null;
 35	
 36	    private bool $policyRead = false;
 37	
 38	    public function choose(int $playerId): ?Alliance
 39	    {
 40	        $policy = $this->policy();
 41	        $rank = (int) Highscore::query()->where('player_id', $playerId)->value('general_rank');
 42	        $population = (int) Highscore::query()->where('general_rank', '>', 0)->count();
 43	
 44	        if ($policy === null || $rank <= 0 || $population <= 0) {
 45	            return null;
 46	        }
 47	
 48	        $ratio = $rank / $population;
 49	        $account = $this->accountFit($playerId);
 50	        $best = null;
 51	        $bestScore = -INF;
 52	
 53	        foreach ($this->openCandidates($playerId) as $alliance) {
 54	            $club = $this->clubFit($alliance);
 55	
 56	            if (! $this->fits($account, $club, $policy['fit'])) {
 57	                continue;
 58	            }
 59	
 60	            $score = $this->tierScore($alliance, $ratio, $policy['tier']) + $this->fitScore($account, $club, $policy['fit']);
 61	
 62	            if ($score > $bestScore) {
 63	                $best = $alliance;
 64	                $bestScore = $score;
 65	            }
 66	        }
 67	
 68	        return $best;
 69	    }
 70	
 71	    /**
 72	     * Whether some open alliance fits the account. Without one the pass's founder half gives the
 73	     * account a club of its own, whose language and pace are the account's own — so the cohort's
 74	     * clubs are founded by accounts of different archetypes instead of all draining into the
 75	     * first club that exists.
 76	     */
 77	    public function hasOpenCandidate(int $playerId): bool
 78	    {
 79	        $policy = $this->policy();
 80	
 81	        if ($policy === null) {
 82	            return $this->openCandidates($playerId) !== [];
 83	        }
 84	
 85	        $account = $this->accountFit($playerId);
 86	
 87	        foreach ($this->openCandidates($playerId) as $alliance) {
 88	            if ($this->fits($account, $this->clubFit($alliance), $policy['fit'])) {
 89	                return true;
 90	            }
 91	        }
 92	
 93	        return false;
 94	    }
 95	
 96	    /**
 97	     * Whether the club the account sits in still fits it: the same language and pace rule that picked
 98	     * it. A club that does not is one a player leaves, which is how a cohort that all joined one club
 99	     * spreads out instead of staying piled into it.
100	     */
101	    public function currentClubFits(int $playerId): bool
102	    {
103	        $policy = $this->policy();
104	        $allianceId = User::query()->whereKey($playerId)->value('alliance_id');
105	        $club = $allianceId === null ? null : Alliance::query()->find($allianceId);
106	
107	        if ($policy === null || $club === null) {
108	            return true;
109	        }
110	
111	        return $this->fits($this->accountFit($playerId), $this->clubFit($club), $policy['fit']);
112	    }
113	
114	    /** @return list<Alliance> */
115	    private function openCandidates(int $playerId): array
116	    {
117	        return array_values(
118	            Alliance::query()
119	                ->where('is_open', true)
120	                ->whereDoesntHave('applications', fn ($query) => $query
121	                    ->where('user_id', $playerId)
122	                    ->where('status', AllianceApplication::STATUS_REJECTED))
123	                ->get()
124	                ->reject(fn (Alliance $alliance): bool => $this->readsFounderAsExploitative($playerId, $alliance))
125	                ->all(),
126	        );
127	    }
128	
129	    /**
130	     * A wary account will not join a club whose founder it models as likely to exploit it, so a
131	     * Defect read removes that alliance from the account's candidates. An absent relationship or
132	     * an absent driver read keeps the alliance in the running, exactly as the native choice did.
133	     */
134	    private function readsFounderAsExploitative(int $playerId, Alliance $alliance): bool
135	    {
136	        return app(PsychSimTheoryOfMind::class)->stanceToward($playerId, (int) $alliance->founder_user_id) === AiToMStance::Defect;
137	    }
138	
139	    /** @return array{language: string|null, band: int|null} */
140	    private function accountFit(int $playerId): array
141	    {
142	        return ['language' => $this->language($playerId), 'band' => $this->band($playerId)];
143	    }
144	
145	    /**
146	     * The club's own language and pace, read from its founder: the one account whose host state
147	     * stands for the club the founder keeps.
148	     *
149	     * @return array{language: string|null, band: int|null}
150	     */
151	    private function clubFit(Alliance $alliance): array
152	    {
153	        $founderId = (int) $alliance->founder_user_id;
154	
155	        return ['language' => $this->language($founderId), 'band' => $this->band($founderId)];
156	    }
157	
158	    /** The account's declared client language, or null when the host holds none. */
159	    private function language(int $playerId): string|null
160	    {
161	        $lang = strtolower(trim((string) User::query()->whereKey($playerId)->value('lang')));
162	
163	        return $lang === '' ? null : $lang;
164	    }
165	
166	    /** How much the account is around, from its own profile; null when it states no pace. */
167	    private function band(int $playerId): int|null
168	    {
169	        // The pace the club or applicant states comes from its own profile row.
170	        return AiProfile::query()->where('player_id', $playerId)->first()?->activity_band?->value;
171	    }
172	
173	    private function fits(array $account, array $club, array $fit): bool
174	    {
175	        if ($account['language'] !== null && $club['language'] !== null && $account['language'] !== $club['language']) {
176	            return false;
177	        }
178	
179	        return $this->bandDistance($account['band'], $club['band']) <= (int) $fit['band']['tolerance'];
180	    }
181	
182	    /** Steps between two paces; an unstated pace on either side is no distance at all. */
183	    private function bandDistance(int|null $account, int|null $club): int
184	    {
185	        if ($account === null || $club === null) {
186	            return 0;
187	        }
188	
189	        return abs($account - $club);
190	    }
191	
192	    private function fitScore(array $account, array $club, array $fit): float
193	    {
194	        return $this->languageScore($account['language'], $club['language'], $fit['language'])
195	            + $this->bandScore($account['band'], $club['band'], $fit['band']);
196	    }
197	
198	    private function languageScore(string|null $account, string|null $club, array $weights): float
199	    {
200	        if ($account === null || $club === null) {
201	            return 0.0;
202	        }
203	
204	        return (float) ($account === $club ? $weights['match'] : $weights['mismatch']);
205	    }
206	
207	    private function bandScore(int|null $account, int|null $club, array $weights): float
208	    {
209	        if ($account === null || $club === null) {
210	            return 0.0;
211	        }
212	
213	        return match ($this->bandDistance($account, $club)) {
214	            0 => (float) $weights['match'],
215	            1 => (float) $weights['neighbour'],
216	            default => (float) $weights['mismatch'],
217	        };
218	    }
219	
220	    private function tierScore(Alliance $alliance, float $rankRatio, array $tier): float
221	    {
222	        $members = (int) AllianceMember::query()->where('alliance_id', $alliance->id)->count();
223	        $points = (int) (AllianceHighscore::query()->where('alliance_id', $alliance->id)->value('general') ?? 0);
224	        // Log scale keeps a million-point elite core comparable with a catch-all's raw size.
225	        $quality = log10(max(1.0, $points / max(1, $members)));
226	        $size = min($members, (int) $tier['size_cap']);
227	        // A readable pitch is the applicant's own filter: demanding alliances write one.
228	        $pitch = trim((string) ($alliance->external_text . $alliance->application_text)) !== '' ? (float) $tier['pitch'] : 0.0;
229	
230	        if ($rankRatio <= (float) $tier['strong_rank_ratio']) {
231	            return $quality * (float) $tier['strong_quality_weight'] + $pitch;
232	        }
233	
234	        if ($rankRatio >= (float) $tier['newbie_rank_ratio']) {
235	            return $size * (float) $tier['newbie_size_weight'] + $pitch;
236	        }
237	
238	        return $quality * (float) $tier['mid_quality_weight'] + $size * (float) $tier['mid_size_weight'] + $pitch;
239	    }
240	
241	    /**
242	     * Read by name from resources/behavior so the fit the cohort invariant states is a number a
243	     * tuning pass moves without touching this class. A missing or unreadable file leaves the
244	     * account with no fit rule: it then weighs clubs on the host's own appeal alone.
245	     *
246	     * @return array<string, mixed>|null
247	     */
248	    private function policy(): array|null
249	    {
250	        if ($this->policyRead) {
251	            return $this->policy;
252	        }
253	
254	        $this->policyRead = true;
255	        $path = dirname(__DIR__, 3) . self::FIT_FILE;
256	        $parsed = is_file($path) ? Yaml::parseFile($path) : null;
257	
258	        return $this->policy = is_array($parsed) ? $parsed : null;
259	    }
260	}

