/**
 * Whether the club already holds the share of the AI cohort the invariant forbids: a club no
 * account asks, and its members leave it one at a time, so the cohort spreads instead of
 * sitting in the club the seeder filled (ALLY-001).
 */
private function holdsCohortShare(Alliance $alliance): bool
{
    $ceiling = $this->recruitmentCeiling();

    if ($ceiling === null) {
        return false;
    }

    $cohort = AiProfile::query()->where('enabled', true)->count();

    if ($cohort < $ceiling['minimum_cohort']) {
        return false;
    }

    $managers = AiProfile::query()->where('enabled', true)->pluck('player_id');

    return AllianceMember::query()->where('alliance_id', $alliance->id)->whereIn('user_id', $managers)->count() / $cohort >= $ceiling['share_ceiling'];
}
```

