    /**
     * Whether the club already holds the share of the AI cohort the invariant forbids. Such a club
     * is no longer asked, and a member of it leaves: the cohort spreads instead of sitting in the
     * club the seeder filled, which is the state where no application is ever created again
     * (ALLY-001). Below minimum_cohort a share means nothing.
     */
    private function holdsCohortShare(Alliance $alliance): bool
    {
        $ceiling = $this->recruitment();

        if ($ceiling === null) {
            return false;
        }

        $managers = $this->aiManagers();
        $cohort = count($managers);

        if ($cohort < $ceiling['minimum_cohort']) {
            return false;
        }

        $members = AllianceMember::query()->where('alliance_id', $alliance->id)->whereIn('user_id', $managers)->count();

        return $members / $cohort >= $ceiling['share_ceiling'];
    }

    /** @return list<int> */
    private function aiManagers(): array
    {
        return $this->aiManagers ??= AiProfile::query()->where('enabled', true)->pluck('player_id')->map(static fn ($id): int => (int) $id)->all();
    }

    /**
     * The share read by name from resources/behavior, so the ceiling the cohort invariant states is
     * one number a tuning pass moves. A missing file leaves the club fit rule in force alone.
     *
     * @return array{share_ceiling: float, minimum_cohort: int}|null
     */
    private function recruitment(): array|null
    {
        if ($this->recruitmentRead) {
            return $this->recruitment;
        }

        $this->recruitmentRead = true;
        $path = dirname(__DIR__, 3) . self::RECRUITMENT_FILE;
        $parsed = is_file($path) ? Yaml::parseFile($path) : null;

        if (!is_array($parsed) || !isset($parsed['share_ceiling'], $parsed['minimum_cohort'])) {
            return $this->recruitment = null;
        }

        return $this->recruitment = [
            'share_ceiling' => (float) $parsed['share_ceiling'],
            'minimum_cohort' => (int) $parsed['minimum_cohort'],
        ];
    }
```

